VALUES ('d7a6e7fa-e8ed-5a1c-8a5c-52d9b3fc644e', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Mô hình OSI gồm bao nhiêu tầng?"}', '{"correct_choice_ids": [0], "general_explanation": "Mô hình OSI (Open Systems Interconnection) gồm 7 tầng: Physical, Data Link, Network, Transport, Session, Presentation, Application."}', 1, 2, ARRAY['mạng','OSI']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('d1b173c3-9b64-560e-a7e0-da0c15ca47ee', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Tầng nào trong mô hình OSI chịu trách nhiệm định tuyến (routing)?"}', '{"correct_choice_ids": [0], "general_explanation": "Tầng Network (tầng 3) chịu trách nhiệm định tuyến gói tin giữa các mạng."}', 1, 2, ARRAY['mạng','OSI','routing']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('abcfb2ff-4211-5d12-a683-86a0e05de137', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Giao thức nào thuộc tầng Transport trong mô hình TCP/IP?"}', '{"correct_choice_ids": [0], "general_explanation": "TCP (Transmission Control Protocol) và UDP (User Datagram Protocol) là hai giao thức chính ở tầng Transport."}', 1, 2, ARRAY['mạng','TCP/IP']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('efa25cb6-7a0c-5ede-bf04-0e7c3f96084d', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Địa chỉ IP phiên bản 4 (IPv4) có bao nhiêu bit?"}', '{"correct_choice_ids": [0], "general_explanation": "IPv4 sử dụng 32 bit, cho phép biểu diễn khoảng 4,3 tỷ địa chỉ."}', 1, 1, ARRAY['mạng','IP']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('bdbffd89-4f7d-550b-bee8-6e12f1286693', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Subnet mask /24 tương đương với giá trị nào?"}', '{"correct_choice_ids": [0], "general_explanation": "/24 nghĩa là 24 bit đầu là 1, tương đương 255.255.255.0."}', 1, 2, ARRAY['mạng','subnet']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('f4ec428d-84f6-5f86-9f45-9c5b20a7add4', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Thiết bị nào hoạt động ở tầng Data Link?"}', '{"correct_choice_ids": [0], "general_explanation": "Switch hoạt động ở tầng Data Link (tầng 2), sử dụng MAC address để chuyển frame."}', 1, 2, ARRAY['mạng','thiết bị']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('d73317f6-7bac-5d68-ac27-5df1a37e1b93', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Giao thức DHCP dùng để làm gì?"}', '{"correct_choice_ids": [0], "general_explanation": "DHCP (Dynamic Host Configuration Protocol) tự động cấp phát IP, subnet mask, gateway cho các thiết bị trong mạng."}', 1, 1, ARRAY['mạng','DHCP']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('6f8a7163-79a3-545f-a2b4-1e550b293d25', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "DNS là viết tắt của gì?"}', '{"correct_choice_ids": [0], "general_explanation": "DNS (Domain Name System) là hệ thống phân giải tên miền thành địa chỉ IP."}', 1, 1, ARRAY['mạng','DNS']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('e9d8096b-3bde-5f42-a2de-6d62fd79b36b', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "VLAN là gì?"}', '{"correct_choice_ids": [0], "general_explanation": "VLAN (Virtual LAN) cho phép phân chia mạng vật lý thành nhiều mạng logic."}', 1, 3, ARRAY['mạng','VLAN']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('cd28c71b-f5d2-5601-b278-3b74c3ed534f', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Giao thức nào được sử dụng để gửi email?"}', '{"correct_choice_ids": [0], "general_explanation": "SMTP (Simple Mail Transfer Protocol) dùng để gửi email, POP3/IMAP dùng để nhận."}', 1, 1, ARRAY['mạng','email']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('c784c545-e442-57c3-9bf4-8eedf0bbcf18', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Lệnh SQL nào dùng để tạo bảng mới?"}', '{"correct_choice_ids": [0], "general_explanation": "CREATE TABLE là câu lệnh DDL dùng để tạo bảng mới trong cơ sở dữ liệu."}', 1, 1, ARRAY['SQL','DDL']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('e4df614f-81b9-565f-8aa2-8202526a30d6', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Ràng buộc nào đảm bảo giá trị trong cột là duy nhất?"}', '{"correct_choice_ids": [0], "general_explanation": "UNIQUE constraint đảm bảo tất cả giá trị trong cột là khác nhau."}', 1, 2, ARRAY['SQL','constraint']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('81753e74-ad48-542b-9cd4-14561c22c69d', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "JOIN nào trả về tất cả bản ghi từ bảng bên trái?"}', '{"correct_choice_ids": [0], "general_explanation": "LEFT JOIN trả về tất cả bản ghi từ bảng bên trái và các bản ghi khớp từ bảng bên phải."}', 1, 2, ARRAY['SQL','JOIN']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('7e03c420-2059-5d29-94b6-37dbdb179c69', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Hàm COUNT(*) dùng để làm gì?"}', '{"correct_choice_ids": [0], "general_explanation": "COUNT(*) đếm tổng số hàng (bản ghi) trong kết quả truy vấn."}', 1, 1, ARRAY['SQL','aggregate']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('5817e8c2-94c8-58cf-9f51-4dd5d5760b7f', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Câu lệnh nào dùng để xóa bảng hoàn toàn?"}', '{"correct_choice_ids": [0], "general_explanation": "DROP TABLE xóa hoàn toàn bảng (cấu trúc + dữ liệu). TRUNCATE chỉ xóa dữ liệu."}', 1, 2, ARRAY['SQL','DDL']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('b12adf25-e2dd-5d2e-9986-86ab1174f8c4', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Từ khóa ORDER BY dùng để làm gì?"}', '{"correct_choice_ids": [0], "general_explanation": "ORDER BY sắp xếp kết quả theo cột chỉ định, mặc định tăng dần (ASC)."}', 1, 1, ARRAY['SQL','query']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
VALUES ('43763d81-9d3b-59a4-b269-916440efa948', '51e467a2-9033-5e85-b666-164ea075f6c9', 'multiple_choice', '{"text": "Stored Procedure trong SQL Server là gì?"}', '{"correct_choice_ids": [0], "general_explanation": "Stored Procedure là tập hợp các câu lệnh SQL được biên dịch sẵn và lưu trên server."}', 1, 3, ARRAY['SQL','stored_procedure']::text[], true, '2025-12-26T08:00:00', '2025-12-26T08:00:00') ON CONFLICT DO NOTHING;
